basicCode.vanilla:
import { createMarkdown } from '@/components/ui/markdown';

const view = createMarkdown({ content: resposta });
document.querySelector('#app')?.append(view);

withStreamingCode.vanilla:
const view = createMarkdown({
  content: parcial,
  streaming: aindaGerando,
  allow: ['paragraph', 'code', 'list'],
});

extensibilityCode.web:
import { parseMarkdown } from '@shared/primitives/markdown-ast';

const tree = parseMarkdown(resposta, { allow: ['paragraph', 'code'] });
const temCodigo = tree.children.some((n) => n.type === 'code');

customizationCode.web:
/* A medida de leitura é da PÁGINA, não do componente. */
.artigo .nds-markdown {
  max-inline-size: 68ch;
}

